parameters.functionScript:
if(!Inputs.Options) return // No options, no fun

// Create objects for all possible options that we will show in the
// dropdown. Use the Selection input to create a Checked property for each.
// Make sure we set id explicitly so it's not rerendered every time
Component.Object.AllOptions = Inputs.Options.map((o,idx) => Noodl.Object.create({
            id:Component.Object.id+'-'+o,
            Value:o,
            Label:Inputs.Labels!==undefined?Inputs.Labels[idx]:o,
            Checked:Inputs.Selection!==undefined && Inputs.Selection.indexOf(o)!==-1
}))

// Create an array with just the checked options
Component.Object.CheckedOptions = Component.Object.AllOptions.filter(o => o.Checked)

// Filter out checked options, this will have changed when the user clicked
// a checkbox or pill
if(!Component.Object.AllOptions) return // Not initialized yet
Component.Object.CheckedOptions = Component.Object.AllOptions.filter(o => o.Checked)

// Create selection from checked options, only return value
Component.Object.Selection = Component.Object.CheckedOptions.map(o => o.Value)

Outputs.Changed()

Component.Object.CheckedOptions = []
Component.Object.Selection = []
if(!Component.Object.AllOptions) return // Not initialized yet
Component.Object.AllOptions.forEach(option => {
    Noodl.Objects[option.id] = {...Noodl.Objects[option.id], Checked: false}
})
